// =====================================================================
// 1. PARAMETER DASAR JARINGAN SARAF TIRUAN (ANN)
// =====================================================================

// sheet.getRange(4, 2) -> Baris 4, Kolom B (2)
// Deskripsi: Nilai Temp (Temperatur) yang digunakan dalam fungsi aktivasi.
const Temp = 1; 

// sheet.getRange(6, 2) -> Baris 6, Kolom B (2)
// Deskripsi: Number of Layers (Total jumlah layer: Input, Hidden, Output).
const nl = 3; 

// sheet.getRange(7, 2) -> Baris 7, Kolom B (2)
// Deskripsi: Number of Node Input Layer (Jumlah fitur input).
const ni = 3; 

// sheet.getRange(8, 2) -> Baris 8, Kolom B (2)
// Deskripsi: Number of Node Hidden Layer.
const nh = 5; 

// sheet.getRange(9, 2) -> Baris 9, Kolom B (2)
// Deskripsi: Number of Node Output Layer.
const no = 2; 

const nn = [];
nn[0] = ni; // Layer 0: Input (3 node)
nn[1] = nh; // Layer 1: Hidden (5 node)
nn[2] = no; // Layer 2: Output (2 node)

// =====================================================================
// 2. AMBIL INPUT DARI MSG.PAYLOAD (Menggantikan a, b, c)
// =====================================================================
const a = msg.payload.a !== undefined ? msg.payload.a : (Array.isArray(msg.payload) ? msg.payload[0] : 0);
const b = msg.payload.b !== undefined ? msg.payload.b : (Array.isArray(msg.payload) ? msg.payload[1] : 0);
const c = msg.payload.c !== undefined ? msg.payload.c : (Array.isArray(msg.payload) ? msg.payload[2] : 0);

const input = [a, b, c];
const xinp = [];

for (let i = 0; i < ni; i++) {
  xinp[i] = input[i];
}

// Inisialisasi array normalisasi input dan output (Sesuai Script Asli)
const maxi = [], mixi = [], maxoCH4 = [], mixoCH4 = [], maxoN2O = [], mixoN2O = [];

// =====================================================================
// 3. PARAMETER MAX DAN MIN INPUT (Kolom D, E, F)
// =====================================================================
// Loop mengambil dari:
// sheet.getRange(28, 4 + i) -> Baris 28 (Max), Kolom D(4), E(5), F(6)
// sheet.getRange(30, 4 + i) -> Baris 30 (Min), Kolom D(4), E(5), F(6)
const staticMaxi = [0.59, 28.60, 1.09]; // [Kelembaban, Suhu, EC] dari baris 28
const staticMixi = [0.47, 25.90, 0.43]; // [Kelembaban, Suhu, EC] dari baris 30

for (let i = 0; i < ni; i++) {
  maxi[i] = staticMaxi[i];
  mixi[i] = staticMixi[i];
}

// =====================================================================
// 4. PARAMETER MAX DAN MIN OUTPUT (Kolom B dan C)
// =====================================================================
// Output CH4
// maxoCH4: sheet.getRange(28, 2) -> Baris 28 (Max), Kolom B(2) = 660.23
// mixoCH4: sheet.getRange(30, 2) -> Baris 30 (Min), Kolom B(2) = 0.45
for (let i = 0; i < no; i++) {
  maxoCH4[i] = 660.23; 
  mixoCH4[i] = 0.45;
}

// Output N2O
// maxoN2O: sheet.getRange(28, 3) -> Baris 28 (Max), Kolom C(3) = 5.40
// mixoN2O: sheet.getRange(30, 3) -> Baris 30 (Min), Kolom C(3) = -25.99
for (let i = 0; i < no; i++) {
  maxoN2O[i] = 5.40; 
  mixoN2O[i] = -25.99;
}

// =====================================================================
// 5. MEMBENTUK MATRIKS BOBOT / WEIGHTS
// =====================================================================
// Script asli: sheet.getRange(2 + TW, 12).getValue() // Kolom L
// Deskripsi: Mengekstrak 25 nilai bobot berurutan dari Baris 3 hingga Baris 27
// dari kolom berisi "Updated Weights" (Sesuai referensi baris di loop TW).
const flatWeights = [
  3.689,   // TW=1  (Baris 3)
  -1.705,  // TW=2  (Baris 4)
  6.790,   // TW=3  (Baris 5)
  -1.350,  // TW=4  (Baris 6)
  -2.728,  // TW=5  (Baris 7)
  2.210,   // TW=6  (Baris 8)
  -5.068,  // TW=7  (Baris 9)
  2.840,   // TW=8  (Baris 10)
  -7.006,  // TW=9  (Baris 11)
  0.853,   // TW=10 (Baris 12)
  5.340,   // TW=11 (Baris 13)
  -7.821,  // TW=12 (Baris 14)
  0.524,   // TW=13 (Baris 15)
  -16.108, // TW=14 (Baris 16)
  21.319,  // TW=15 (Baris 17)
  9.766,   // TW=16 (Baris 18)
  -5.564,  // TW=17 (Baris 19)
  -0.119,  // TW=18 (Baris 20)
  -5.619,  // TW=19 (Baris 21)
  -7.975,  // TW=20 (Baris 22)
  -8.519,  // TW=21 (Baris 23)
  -1.050,  // TW=22 (Baris 24)
  7.647,   // TW=23 (Baris 25)
  0.996,   // TW=24 (Baris 26)
  9.795    // TW=25 (Baris 27)
];

// Re-konstruksi Array 3D sesuai script asli
let TW_index = 0; // Pengganti referensi iterasi range (karena data sudah di array)
const w = [];

for (let l = 1; l < nl; l++) {
  w[l - 1] = [];
  for (let j = 0; j < nn[l]; j++) {
    w[l - 1][j] = [];
    for (let k = 0; k < nn[l - 1]; k++) {
      w[l - 1][j][k] = flatWeights[TW_index];
      TW_index++;
    }
  }
}

// =====================================================================
// 6. NORMALISASI INPUT
// =====================================================================
for (let i = 0; i < ni; i++) {
  xinp[i] = (xinp[i] - mixi[i]) / (maxi[i] - mixi[i]);
}

// =====================================================================
// 7. PROSES FORWARD PROPAGATION
// =====================================================================
const X = [];
X[0] = xinp;

for (let l = 1; l < nl; l++) {
  X[l] = [];
  for (let j = 0; j < nn[l]; j++) {
    let sum = 0;
    for (let k = 0; k < nn[l - 1]; k++) {
      sum += w[l - 1][j][k] * X[l - 1][k];
    }
    // Rumus Sigmoid Bipolar/Khusus sesuai script
    X[l][j] = 1 / (1 + Temp * Math.exp(-sum));
  }
}

// =====================================================================
// 8. DENORMALISASI OUTPUT (Sesuai perhitungan array asli)
// =====================================================================
// Denormalisasi output CH4
const CH4 = (X[nl - 1][0] - 0.2) * (maxoCH4[0] - mixoCH4[0]) / 0.6 + mixoCH4[0];

// Denormalisasi output N2O
const N2O = (X[nl - 1][1] - 0.2) * (maxoN2O[0] - mixoN2O[0]) / 0.6 + mixoN2O[0];

// =====================================================================
// 9. RETURN KE PAYLOAD NODE-RED (Menggantikan `return [CH4, N2O]`)
// =====================================================================
msg.payload = {
  data :{
    CH4: CH4,
    N2O: N2O,
    soil_moisture : a*100,
    soil_temperature :b,
    electrical_conductivity:c,
    battery:msg.payload.batV,
    rssi:msg.payload.rssi,
    snr:msg.payload.snr
  },
  timestamp:msg.payload.time,
  deviceName:msg.payload.deviceName,
  deviceType:msg.payload.deviceType
};

return msg;

let data = (typeof msg.payload === "string") ? JSON.parse(msg.payload) : msg.payload;

let temp = data.object?.temp_SOIL || 0;
let soil = data.object?.water_SOIL || 0;
let ec = data.object?.conduct_SOIL || 0;
let bat = data.object?.BatV || 0;
let time = data.time || null;
let deviceName = data.deviceInfo?.deviceName || "unknown_device";
let deviceType = data.deviceInfo?.deviceProfileName || "unknown_type";
let rssi =data.rxInfo[0]?.rssi|| null;
let snr = data.rxInfo[0]?.snr || null;

msg.payload = {
  "a":soil/100,
  "b":temp,
  "c":ec,
  "time":time,
  "deviceName":deviceName,
  "deviceType":deviceType,
  "batV":bat,
  "rssi":rssi,
  "snr":snr

}

return msg;

let data = (typeof msg.payload === "string") ? JSON.parse(msg.payload) : msg.payload;

let time = data.timestamp || "";
let deviceName = data?.deviceName || "unknown_device";
let deviceType = data?.deviceType || "unknown_type";

let csvLine = "";

if (deviceType === "WL") {
    let temp = data.object?.Sensor_Temp || "";
    let wl = data.object?.Sensor_WL || "";
    let bat = data.object?.BatV || "";
    let exti = data.object?.EXTI_Trigger || "";
    csvLine = `${time},${deviceName},${temp},${wl},${bat},${exti}\n`;
}

else if (deviceType === "SOIL") {
    let temp = data.data?.soil_temperature || "";
    let soil = data.data?.soil_moisture || "";
    let ec = data.data?.electrical_conductivity || "";
    let ch4 = data.data?.CH4 || "";
    let n2o = data.data?.N2O || "";
    let bat = data.data?.bat || "";
    csvLine = `${time},${deviceName},${temp},${soil},${ec},${ch4},${n2o},${bat}\n`;
}
else {
    csvLine = `${time},${deviceName},Unknown device type: ${deviceType}\n`;
}

msg.payload = csvLine;
msg.filename = `/media/usb0/${deviceName}.csv`;  // ganti sesuai OS-mu

return msg;

// Parse payload
let input = (typeof msg.payload === "string")
    ? JSON.parse(msg.payload)
    : msg.payload;

// Validasi
if (!input || typeof input !== "object") {
    node.error("Payload tidak valid", msg);
    return null;
}

// Device name
let deviceName = input.deviceName || "unknown_device";

// Bersihkan nama device
// "Sensor Soil 1" → "Sensor_Soil_1"
let deviceKey = deviceName
    .trim()
    .replace(/\s+/g, "_")
    .replace(/[^a-zA-Z0-9_-]/g, "_");

// Ambil data sensor
let sensorData = input.data || {};

// Simpan parameter
for (let key in sensorData) {

    let value = sensorData[key];

    // Konversi string angka menjadi number
    if (
        typeof value === "string" &&
        value.trim() !== "" &&
        !isNaN(value)
    ) {
        value = Number(value);
    }

    // Bersihkan nama parameter
    let parameterKey = key
        .trim()
        .replace(/\s+/g, "_")
        .replace(/[^a-zA-Z0-9_-]/g, "_");

    // Contoh:
    // Sensor_Soil_1_CH4
    // Sensor_Soil_1_soil_moisture
    let dynamicKey = `${deviceKey}_${parameterKey}`;

    flow.set(dynamicKey, value);
}

// Simpan metadata
flow.set(`${deviceKey}_timestamp`, input.timestamp || null);
flow.set(`${deviceKey}_deviceType`, input.deviceType || null);

// Output
msg.payload = {
    status: "Data berhasil disimpan",
    device: deviceKey,
    keys: Object.keys(sensorData).map(key => {
        let parameterKey = key
            .trim()
            .replace(/\s+/g, "_")
            .replace(/[^a-zA-Z0-9_-]/g, "_");

        return `${deviceKey}_${parameterKey}`;
    })
};

return msg;

// Ambil semua key dari flow context
let contextKeys = flow.keys();

// Object untuk menyimpan semua data
let result = {};

// Ambil semua value
for (let key of contextKeys) {
    result[key] = flow.get(key);
}

// Output
msg.payload = result;

return msg;

function encodeForm(obj) {
    return Object.keys(obj)
        .map(k => encodeURIComponent(k) + "=" + encodeURIComponent(obj[k]))
        .join("&");
}

