    pad(now.getSeconds());

const bodyData = {
    datetime: datetime,
    device_id: "388",  // Bisa kamu ubah jika perlu spesifik
    c1: data["Soil_Dry_1_soil_moisture"] || 0,
    c2: data["Soil_Dry_1_soil_temperature"] || 0,
    c3: data["Soil_Dry_1_electrical_conductivity"] || 0,
    c4: data["Soil_Dry_1_battery"] || 0,
    c5: data["Soil_Dry_2_soil_moisture"] || 0,
    c6: data["Soil_Dry_2_soil_temperature"] || 0,
    c7: data["Soil_Dry_2_electrical_conductivity"] || 0,
    c8: data["Soil_Dry_2_battery"] || 0,
    c9: data["Soil_Wet_1_soil_moisture"] || 0,
    c10: data["Soil_Wet_1_soil_temperature"] || 0,
    c11: data["Soil_Wet_1_electrical_conductivity"] || 0,
    c12: data["Soil_Wet_1_battery"] || 0,
    c13: data["Soil_Wet_2_soil_moisture"] || 0,
    c14: data["Soil_Wet_2_soil_temperature"] || 0,
    c15: data["Soil_Wet_2_electrical_conductivity"] || 0,
    c16: data["Soil_Wet_2_battery"] || 0,
    c17: data["Soil_Dry_1_CH4"] || 0,
    c18: data["Soil_Dry_1_N2O"] || 0,
    c19: data["Soil_Dry_2_CH4"] || 0,
    c20: data["Soil_Dry_2_N2O"] || 0,
    c21: data["Soil_Wet_1_CH4"] || 0,
    c22: data["Soil_Wet_1_N2O"] || 0,
    c23: data["Soil_Wet_2_CH4"] || 0,
    c24: data["Soil_Wet_2_N2O"] || 0
};

msg.method = "POST";
msg.url = "https://api.dataonline.co.id/v1/storeData?"; // ← Ganti dengan URL API kamu
msg.headers = {
    "api_token": "Zk1VeVhrM0hzTUJZM1lFYXFnS3czdm9LMkExNGY5emU=",  // ← Ganti dengan token kamu
    "Content-Type": "application/x-www-form-urlencoded",
    "Connection":"keep-alive",

};
msg.payload = encodeForm(bodyData);

return msg;

// Ambil semua key dari flow context
let contextKeys = flow.keys();

let result = {};

// Device yang diperbolehkan
let allowedDevices = {
    "Soil_Dry_1": "dry1",
    "Soil_Dry_2": "dry2",
    "Soil_Wet_1": "wet1",
    "Soil_Wet_2": "wet2"
};

// Loop semua data
for (let key of contextKeys) {

    let value = flow.get(key);

    // Cari device berdasarkan prefix
    for (let device of Object.keys(allowedDevices)) {

        let prefix = device + "_";

        if (key.startsWith(prefix)) {

            // Ambil nama parameter setelah nama device
            let parameter = key.substring(prefix.length);

            // Nama baru
            let newKey = allowedDevices[device] + "_" + parameter;

            result[newKey] = value;

            break;
        }
    }
}

// Buat payload
msg.payload = {
    timestamp: new Date().toISOString(),
    data: result
};

return msg;
